    Bug 1923867 - Opening Account Manager produces error in console - Failed to set favicon for page:[Exception... "Component is not available"  nsresult: "0x80040111 (NS_ERROR_NOT_AVAILABLE)". r=tobyp

    Doesn't make sense to create a page icon for internal pages such as about:accountsettings.
    It's only supposed to be used for http(s) pages.

    Differential Revision: https://phabricator.services.mozilla.com/D226653

diff --git a/mail/base/content/specialTabs.js b/mail/base/content/specialTabs.js
index 1f44278aa24..025dc1deab0 100644
--- a/mail/base/content/specialTabs.js
+++ b/mail/base/content/specialTabs.js
@@ -1287,11 +1287,11 @@ var specialTabs = {
    * page shown in the browser. It is assumed that the preferences have already
    * been checked before calling this function appropriately.
    *
-   * @param aTab  The tab to set the icon for.
-   * @param aIcon A string based URL of the icon to try and load.
+   * @param {object} aTab - The tab (tabInfo) to set the icon for.
+   * @param {string} aIcon - A string based URL of the icon to try and load.
    */
   async setFavIcon(aTab, aIcon) {
-    if (aIcon) {
+    if (aIcon && aTab.browser.currentURI.spec.startsWith("http")) {
       const iconURI = Services.io.newURI(aIcon);
       await MailUtils.setFaviconForPage(aTab.browser.currentURI, iconURI);
     }
diff --git a/mail/modules/MailUtils.sys.mjs b/mail/modules/MailUtils.sys.mjs
index 73cc0657c49..eb263828eb4 100644
--- a/mail/modules/MailUtils.sys.mjs
+++ b/mail/modules/MailUtils.sys.mjs
@@ -1073,12 +1073,16 @@ export var MailUtils = {
   },

   /**
-   * Set the favicon for the currently visited page.
+   * Set the favicon for the currently visited http(s) page in the favicons db.
    *
    * @param {nsIURI} pageURI
    * @param {nsIURI} iconURI
    */
   async setFaviconForPage(pageURI, iconURI) {
+    if (!pageURI.schemeIs("http") && !pageURI.schemeIs("https")) {
+      // Don't try to store favion if this isn't a http(s) page.
+      return;
+    }
     try {
       // If the given faviconURI is data URL, set it as is.
       if (iconURI.schemeIs("data")) {
@@ -1106,7 +1110,7 @@ export var MailUtils = {
         dataURL
       );
     } catch (ex) {
-      console.error(`Failed to set favicon for page:${ex}`);
+      console.error(`Set favicon for page ${pageURI.spec} FAILED`, ex);
     }
   },
